use crate::encounter_store;
use std::{fs, path::{Path, PathBuf}};

const ARCHIVE_FILE: &str = "index.html";

pub fn generate(root: &Path) -> Result<PathBuf, String> {
    let dir = encounter_store::dir(root);
    fs::create_dir_all(&dir).map_err(|e| format!("create encounter history folder: {e}"))?;
    let records = encounter_store::load_recent(root, encounter_store::DEFAULT_LIMIT);
    let mut json = serde_json::to_string(&records).map_err(|e| format!("serialize encounter history: {e}"))?;
    json = json.replace('&', "\\u0026").replace('<', "\\u003c").replace('>', "\\u003e");

    let mut html = String::with_capacity(json.len().saturating_add(30_000));
    html.push_str(HTML_HEAD);
    html.push_str(&json);
    html.push_str(HTML_TAIL);

    let target = dir.join(ARCHIVE_FILE);
    let pending = dir.join("index.html.new");
    fs::write(&pending, html.as_bytes()).map_err(|e| format!("write encounter history: {e}"))?;
    if target.exists() {
        fs::remove_file(&target).map_err(|e| format!("replace old encounter history: {e}"))?;
    }
    fs::rename(&pending, &target).map_err(|e| format!("install encounter history: {e}"))?;
    Ok(target)
}

const HTML_HEAD: &str = r#"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'">
<title>BPSR ReadyAlert Encounter History</title>
<style>
:root{color-scheme:dark;--bg:#0e1116;--panel:#151a21;--panel2:#1b222b;--line:#29323d;--text:#e8edf3;--muted:#8793a3;--accent:#65c9ff;--good:#75d49b;--warn:#f0c55f;--hover:#202833}
*{box-sizing:border-box}[hidden]{display:none!important}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font:14px/1.45 "Segoe UI",system-ui,-apple-system,sans-serif}button,input{font:inherit;color:inherit}.shell{display:grid;grid-template-columns:350px minmax(0,1fr);min-height:100vh}.left{position:sticky;top:0;height:100vh;border-right:1px solid var(--line);background:#11161c;display:flex;flex-direction:column}.brand{padding:17px 16px 12px;border-bottom:1px solid var(--line)}.brand h1{font-size:16px;margin:0}.brand p{font-size:12px;color:var(--muted);margin:3px 0 0}.local{color:#9ed9af;margin-top:7px;font-size:11px}.tools{display:flex;gap:7px;padding:10px 10px 0}.tool{border:1px solid #34404d;background:#192129;border-radius:7px;padding:7px 10px;cursor:pointer;font-size:12px}.tool:hover{background:#22303b}.tool.primary{border-color:#356079}.tool:disabled{opacity:.45;cursor:default}.compare-count{margin-left:auto;align-self:center;color:var(--muted);font-size:11px}.search-wrap{padding:10px;border-bottom:1px solid var(--line)}.search{width:100%;height:35px;border-radius:7px;border:1px solid #343e4a;background:var(--panel);padding:0 10px;outline:none}.search:focus{border-color:#4e94ba;box-shadow:0 0 0 2px rgba(101,201,255,.12)}.enc-list{overflow:auto;padding:8px;flex:1}.enc-row{display:grid;grid-template-columns:24px minmax(0,1fr);align-items:stretch;margin-bottom:3px;border-radius:8px}.check-wrap{display:flex;align-items:center;justify-content:center}.compare-check{width:15px;height:15px;accent-color:#65c9ff;cursor:pointer}.enc-card{width:100%;border:1px solid transparent;background:transparent;border-radius:8px;padding:9px 10px;text-align:left;cursor:pointer}.enc-card:hover{background:var(--hover)}.enc-card.active{background:#1e2a35;border-color:#30485b}.enc-title{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.enc-meta{display:flex;gap:6px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin-top:4px}.enc-stat{display:flex;justify-content:space-between;gap:8px;margin-top:6px;font-size:12px;color:#b9c3cf}.main{min-width:0}.top{position:sticky;top:0;z-index:10;background:rgba(14,17,22,.96);backdrop-filter:blur(12px);border-bottom:1px solid var(--line);padding:16px 22px}.title-row{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.top h2{font-size:20px;margin:0}.subtitle{color:var(--muted);font-size:12px;margin-top:4px}.pills{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid #34404d;border-radius:999px;padding:4px 8px;color:#b8c4d0;font-size:11px;background:#171d25}.content{max-width:1240px;margin:0 auto;padding:18px 22px 60px}.hero{display:grid;grid-template-columns:repeat(5,minmax(110px,1fr));gap:10px;margin-bottom:16px}.metric{background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:11px}.metric .k{font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.metric .v{font-size:19px;font-weight:700;margin-top:2px;font-variant-numeric:tabular-nums}.layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:14px}.players,.detail{background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden}.section-head{padding:11px 13px;border-bottom:1px solid var(--line);font-size:12px;font-weight:700;color:#cbd4de}.player-list{padding:6px}.player{width:100%;border:0;background:transparent;text-align:left;border-radius:7px;padding:8px 9px;cursor:pointer;display:grid;grid-template-columns:28px minmax(0,1fr);gap:4px}.player:hover{background:var(--hover)}.player.active{background:#202d38}.rank{font-weight:750;color:#91a3b6;font-variant-numeric:tabular-nums;text-align:center;padding-top:1px}.player-name{font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player-sub{grid-column:2;color:var(--muted);font-size:11px;margin-top:-1px}.tabs{display:flex;gap:2px;padding:7px 8px;border-bottom:1px solid var(--line);overflow:auto}.tab{border:0;background:transparent;padding:7px 9px;border-radius:6px;cursor:pointer;color:#aeb9c5;white-space:nowrap;font-size:12px}.tab:hover{background:var(--hover)}.tab.active{background:#253441;color:#fff}.pane{padding:13px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.mini{background:var(--panel2);border:1px solid #29333f;border-radius:8px;padding:10px}.mini .label{color:var(--muted);font-size:11px}.mini .value{font-size:16px;font-weight:650;margin-top:2px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table{width:100%;border-collapse:collapse;min-width:650px}.table th,.table td{padding:8px 10px;border-bottom:1px solid #27303a;text-align:right;font-variant-numeric:tabular-nums}.table th{position:sticky;top:0;background:#192028;color:#8f9bab;font-size:10px;text-transform:uppercase;letter-spacing:.05em}.table th:first-child,.table td:first-child{text-align:left}.table tr:last-child td{border-bottom:0}.sort-btn{border:0;background:transparent;color:inherit;padding:0;cursor:pointer;text-transform:inherit;letter-spacing:inherit;font:inherit}.sort-btn:hover{color:#dce9f5}.sort-arrow{display:inline-block;min-width:10px;margin-left:3px;color:var(--accent)}.muted{color:var(--muted)}.recap{border:1px solid var(--line);border-radius:8px;margin-bottom:9px;overflow:hidden}.recap-head{padding:8px 10px;background:#251b1d;color:#ffc0c0;font-weight:650}.event{display:grid;grid-template-columns:70px 72px minmax(0,1fr) 100px;gap:8px;padding:7px 9px;border-top:1px solid var(--line);font-size:12px}.heal{color:#8de0aa}.damage{color:#f0a0a0}.empty{padding:60px 20px;text-align:center;color:var(--muted)}.empty strong{display:block;color:#cdd6df;font-size:17px;margin-bottom:5px}.footer{padding:22px;text-align:center;color:#657180;font-size:11px}.compare-top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.compare-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.compare-panel{background:var(--panel);border:1px solid var(--line);border-radius:10px;overflow:hidden;min-width:0}.compare-head{padding:13px;border-bottom:1px solid var(--line)}.compare-head h3{margin:0;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.compare-body{padding:12px}.compare-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-bottom:11px}.compare-player{display:grid;grid-template-columns:27px minmax(0,1fr) auto;gap:7px;align-items:center;border-top:1px solid #252e38;padding:7px 2px}.compare-player:first-child{border-top:0}.compare-player .name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.compare-player .value{font-variant-numeric:tabular-nums;font-weight:650}.bench{color:#9fd7ff}
@media(max-width:1050px){.shell{grid-template-columns:290px minmax(0,1fr)}.hero{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:220px minmax(0,1fr)}}@media(max-width:820px){.compare-grid{grid-template-columns:1fr}}@media(max-width:720px){.shell{display:block}.left{position:relative;height:auto;max-height:420px;border-right:0;border-bottom:1px solid var(--line)}.enc-list{max-height:270px}.top{position:relative}.hero{grid-template-columns:repeat(2,1fr)}.layout{display:block}.players{margin-bottom:12px}.player-list{display:flex;overflow:auto}.player{min-width:185px}.content{padding:12px 10px 40px}.event{grid-template-columns:54px 60px minmax(0,1fr)}.tools{flex-wrap:wrap}}
</style>
</head>
<body>
<div class="shell">
<aside class="left">
<div class="brand"><h1>BPSR ReadyAlert</h1><p>Encounter History</p><div class="local">Offline / stored only on this PC</div></div>
<div class="tools"><button id="refresh" class="tool" type="button">Refresh</button><button id="compare-btn" class="tool primary" type="button" disabled>Compare</button><span id="compare-count" class="compare-count">0 / 2</span></div>
<div class="search-wrap"><input id="search" class="search" type="search" autocomplete="off" placeholder="Search dungeon, benchmark, boss or player…"></div>
<div id="enc-list" class="enc-list"></div>
</aside>
<main class="main"><div id="app"></div></main>
</div>
<script>const DATA="#;

const HTML_TAIL: &str = r#";
const $=s=>document.querySelector(s),list=$('#enc-list'),app=$('#app'),search=$('#search'),compareBtn=$('#compare-btn'),compareCount=$('#compare-count');
let filtered=DATA,selectedId=DATA[0]?.id??null,selectedPlayer=0,tab='overview',compareIds=[],compareMode=false,skillSort={key:'score',dir:-1};
const num=n=>(Number(n)||0).toLocaleString();
const compact=n=>{n=Number(n)||0;const a=Math.abs(n);if(a>=1e9)return (n/1e9).toFixed(a>=1e10?1:2)+'B';if(a>=1e6)return (n/1e6).toFixed(a>=1e7?1:2)+'M';if(a>=1e3)return (n/1e3).toFixed(a>=1e4?1:2)+'K';return num(n)};
const dur=ms=>{ms=Number(ms)||0;const s=Math.floor(ms/1000),m=Math.floor(s/60),r=s%60;return m?`${m}:${String(r).padStart(2,'0')}`:`${r}s`};
const pct=(a,b)=>b>0?`${(100*a/b).toFixed(1)}%`:'—';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=ms=>{const d=new Date(Number(ms)||0);return isNaN(d)?'Unknown time':d.toLocaleString()};
const isBenchmark=e=>(Number(e.context?.benchmark_duration_ms)||0)>0;
const encounterTitle=e=>isBenchmark(e)?`Benchmark - ${e.context?.benchmark_name||'Unnamed'} (${Math.round((e.context?.benchmark_duration_ms||0)/1000)}s)`:(e.context?.scene_name||e.target_name||`Scene ${e.context?.scene_id||'Unknown'}`);
const difficulty=e=>e.context?.difficulty||'';
const playLabel=e=>isBenchmark(e)?'Benchmark':({2:'Dungeon',3:'Memory',5:'Race',6:'Event',8:'Unstable',9:'Dungeon',12:'Guild',13:'Guild Hunt',15:'World Boss',16:'Tower',17:'Master Dungeon',18:'Season Challenge',19:'Season Dungeon',20:'Event'}[e.context?.play_type]||'Encounter');
const byDamage=e=>[...(e.snapshot?.rows||[])].sort((a,b)=>(b.damage||0)-(a.damage||0));
function selectedEncounter(){return filtered.find(e=>e.id===selectedId)||filtered[0]||null;}
function updateCompareUi(){compareCount.textContent=`${compareIds.length} / 2`;compareBtn.disabled=compareIds.length!==2;}
function toggleCompare(id,checked){if(checked){if(!compareIds.includes(id)){if(compareIds.length>=2)compareIds.shift();compareIds.push(id);}}else{compareIds=compareIds.filter(x=>x!==id);compareMode=false;}updateCompareUi();renderList();if(compareIds.length===2){compareMode=true;renderDetail();}else if(compareMode){compareMode=false;renderDetail();}}
function renderList(){list.innerHTML='';if(!filtered.length){list.innerHTML='<div class="empty"><strong>No encounters</strong>No saved encounter matches this search.</div>';updateCompareUi();return;}filtered.forEach(e=>{const rows=byDamage(e),top=rows[0],row=document.createElement('div');row.className='enc-row';const checked=compareIds.includes(e.id);row.innerHTML=`<label class="check-wrap" title="Select for comparison"><input class="compare-check" type="checkbox" ${checked?'checked':''}></label><button class="enc-card${e.id===selectedId&&!compareMode?' active':''}" type="button"><div class="enc-title${isBenchmark(e)?' bench':''}">${esc(encounterTitle(e))}</div><div class="enc-meta"><span>${esc(when(e.ended_unix_ms))}</span>${difficulty(e)?`<span>• ${esc(difficulty(e))}</span>`:''}<span>• ${dur(e.snapshot?.encounter_ms)}</span></div><div class="enc-stat"><span>${rows.length} players</span><span>${compact(e.snapshot?.total_damage)} dmg${top?` · ${esc(top.name)}`:''}</span></div></button>`;row.querySelector('.compare-check').addEventListener('change',ev=>toggleCompare(e.id,ev.target.checked));row.querySelector('.enc-card').onclick=()=>{selectedId=e.id;selectedPlayer=0;tab='overview';compareMode=false;renderList();renderDetail()};list.appendChild(row)});updateCompareUi();}
function renderDetail(){if(compareMode&&compareIds.length===2){renderComparison();return;}const e=selectedEncounter();if(!e){app.innerHTML='<div class="empty"><strong>No encounter selected</strong>Complete a combat encounter and it will appear here.</div>';return;}const s=e.snapshot||{},rows=byDamage(e),target=s.target?.name||e.target_name||'Encounter';app.innerHTML=`<header class="top"><div class="title-row"><div><h2>${esc(encounterTitle(e))}</h2><div class="subtitle">${esc(target)} · ${esc(when(e.ended_unix_ms))}</div></div><div class="pills"><span class="pill">${esc(playLabel(e))}</span>${difficulty(e)?`<span class="pill">${esc(difficulty(e))}</span>`:''}${e.context?.scene_id?`<span class="pill">Scene ${e.context.scene_id}</span>`:''}</div></div></header><div class="content"><section class="hero">${metric('Duration',dur(s.encounter_ms))}${metric('Damage',compact(s.total_damage))}${metric('Healing',compact(s.total_healing))}${metric('Damage taken',compact(s.total_damage_taken))}${metric('Players',rows.length)}</section><div class="layout"><section class="players"><div class="section-head">Players</div><div id="players" class="player-list"></div></section><section class="detail"><div class="tabs" id="tabs"></div><div class="pane" id="pane"></div></section></div><div class="footer">Saved locally by ReadyAlert · use Refresh to load newly completed encounters</div></div>`;renderPlayerList(e,rows);renderTabs();renderPane(e,rows[selectedPlayer]);}
const metric=(k,v)=>`<div class="metric"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div></div>`;
function renderPlayerList(e,rows){const p=$('#players');p.innerHTML='';rows.forEach((r,i)=>{const b=document.createElement('button');b.className='player'+(i===selectedPlayer?' active':'');b.innerHTML=`<span class="rank">${i+1}</span><span class="player-name">${esc(r.name||`Player ${r.uid||''}`)}</span><span class="player-sub">${esc(r.subprofession_name||'Unknown spec')} · ${compact(r.damage)} dmg · ${r.deaths||0} death${r.deaths===1?'':'s'}</span>`;b.onclick=()=>{selectedPlayer=i;document.querySelectorAll('.player').forEach((x,j)=>x.classList.toggle('active',j===i));renderPane(e,rows[i])};p.appendChild(b)});}
function renderTabs(){const tabs=[['overview','Overview'],['skills','Skills'],['buffs','Buffs'],['deaths','Deaths'],['taken','Damage Taken']];const el=$('#tabs');el.innerHTML='';tabs.forEach(([id,label])=>{const b=document.createElement('button');b.className='tab'+(id===tab?' active':'');b.textContent=label;b.onclick=()=>{tab=id;renderTabs();const e=selectedEncounter(),rows=e?byDamage(e):[];renderPane(e,rows[selectedPlayer])};el.appendChild(b)});}
function renderPane(e,r){const pane=$('#pane');if(!r){pane.innerHTML='<div class="empty"><strong>No player rows</strong>This encounter did not contain player contribution data.</div>';return;}if(tab==='overview'){pane.innerHTML=`<div class="grid2">${mini('Damage / DPS',`${compact(r.damage)} / ${compact(r.dps)}`)}${mini('Active DPS',compact(r.active_dps))}${mini('Healing / effective',`${compact(r.healing)} / ${compact(r.effective_healing)}`)}${mini('Overhealing',compact(r.overhealing))}${mini('Damage taken / absorbed',`${compact(r.damage_taken)} / ${compact(r.absorbed_damage)}`)}${mini('Hits · Crit · Lucky',`${num(r.hits)} · ${pct(r.crits,r.hits)} · ${pct(r.lucky_hits,r.hits)}`)}${mini('Boss damage',`${compact(r.boss_damage)} (${pct(r.boss_damage,r.damage)})`)}${mini('Deaths',num(r.deaths))}</div>`;return;}if(tab==='skills'){renderSkills(pane,r);return;}if(tab==='buffs'){const buffs=[...(r.buff_uptimes||[])].sort((a,b)=>(b.uptime_ms||0)-(a.uptime_ms||0));pane.innerHTML=buffs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Buff</th><th>Uptime</th><th>Time</th><th>Activations</th></tr></thead><tbody>${buffs.map(x=>`<tr><td>${esc(x.name||`Buff ${x.buff_id}`)}</td><td>${pct(x.uptime_ms,e.snapshot.encounter_ms)}</td><td>${dur(x.uptime_ms)}</td><td>${num(x.activations)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No named buff uptime</strong>No supported buff uptime data was retained for this player.</div>';return;}if(tab==='deaths'){const recaps=r.death_recaps||[];pane.innerHTML=recaps.length?recaps.map(d=>`<div class="recap"><div class="recap-head">Death ${d.death_no} · ${dur(d.at_ms)} into encounter</div>${(d.events||[]).map(x=>`<div class="event"><span>${dur(x.at_ms)}</span><span class="${x.is_heal?'heal':'damage'}">${x.is_heal?'HEAL':'HIT'}</span><span>${esc(x.source_name||'Unknown')} · ${esc(x.skill_name||`Skill ${x.skill_id}`)}</span><strong>${compact(x.value)}</strong></div>`).join('')}</div>`).join(''):'<div class="empty"><strong>No death recap</strong>This player had no recorded deaths in the encounter.</div>';return;}if(tab==='taken'){const src=[...(r.taken_sources||[])].sort((a,b)=>(b.damage||0)-(a.damage||0)),abs=[...(r.absorbed_sources||[])].sort((a,b)=>(b.damage||0)-(a.damage||0));const table=(rows,label)=>rows.length?`<div class="section-head" style="margin:10px 0 6px;padding-left:0;border:0">${label}</div><div class="table-wrap"><table class="table"><thead><tr><th>Source / skill</th><th>Amount</th><th>Hits</th><th>Crit</th><th>Lucky</th><th>Max</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.source_name||'Unknown')} · ${esc(x.skill_name||`Skill ${x.skill_id}`)}</td><td>${compact(x.damage)}</td><td>${num(x.hits)}</td><td>${pct(x.crits,x.hits)}</td><td>${pct(x.lucky_hits,x.hits)}</td><td>${compact(x.max_value)}</td></tr>`).join('')}</tbody></table></div>`:'';pane.innerHTML=(table(src,'HP damage taken')+table(abs,'Direct absorbed / shield events'))||'<div class="empty"><strong>No incoming breakdown</strong>No supported incoming damage sources were retained.</div>';}}
const mini=(label,value)=>`<div class="mini"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div></div>`;
const skillCols=[['name','Skill'],['damage','Damage'],['boss_damage','Boss'],['healing','Healing'],['hits','Hits'],['crit','Crit'],['lucky','Lucky'],['min_value','Min'],['max_value','Max']];
function skillValue(x,key){if(key==='name')return String(x.name||`Skill ${x.skill_id}`).toLocaleLowerCase();if(key==='crit')return x.hits?x.crits/x.hits:0;if(key==='lucky')return x.hits?x.lucky_hits/x.hits:0;if(key==='score')return (Number(x.damage)||0)+(Number(x.healing)||0);return Number(x[key])||0;}
function renderSkills(pane,r){let skills=[...(r.skills||[])];skills.sort((a,b)=>{const av=skillValue(a,skillSort.key),bv=skillValue(b,skillSort.key);if(typeof av==='string')return skillSort.dir*av.localeCompare(bv);return skillSort.dir*(av-bv)});if(!skills.length){pane.innerHTML='<div class="empty"><strong>No skill breakdown</strong>No outgoing skill events were retained for this player.</div>';return;}const head=skillCols.map(([key,label])=>`<th><button type="button" class="sort-btn" data-sort="${key}">${label}<span class="sort-arrow">${skillSort.key===key?(skillSort.dir===1?'↑':'↓'):''}</span></button></th>`).join('');pane.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr>${head}</tr></thead><tbody>${skills.map(x=>`<tr><td>${esc(x.name||`Skill ${x.skill_id}`)}</td><td>${compact(x.damage)}</td><td>${compact(x.boss_damage)}</td><td>${compact(x.healing)}</td><td>${num(x.hits)}</td><td>${pct(x.crits,x.hits)}</td><td>${pct(x.lucky_hits,x.hits)}</td><td>${x.min_value?compact(x.min_value):'—'}</td><td>${x.max_value?compact(x.max_value):'—'}</td></tr>`).join('')}</tbody></table></div>`;pane.querySelectorAll('[data-sort]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.sort;if(skillSort.key===key)skillSort.dir*=-1;else{skillSort.key=key;skillSort.dir=key==='name'?1:-1;}renderSkills(pane,r)});}
function renderComparison(){const pair=compareIds.map(id=>DATA.find(e=>e.id===id)).filter(Boolean);if(pair.length!==2){compareMode=false;renderDetail();return;}app.innerHTML=`<header class="top"><div class="title-row"><div><h2>Encounter Comparison</h2><div class="subtitle">Two saved encounters side by side</div></div><button id="exit-compare" class="tool" type="button">Exit comparison</button></div></header><div class="content"><div class="compare-grid">${pair.map(comparePanel).join('')}</div><div class="footer">Comparison is local only · use Refresh to load newly completed encounters</div></div>`;$('#exit-compare').onclick=()=>{compareMode=false;renderList();renderDetail()};}
function comparePanel(e){const s=e.snapshot||{},rows=byDamage(e);return `<section class="compare-panel"><div class="compare-head"><h3 class="${isBenchmark(e)?'bench':''}">${esc(encounterTitle(e))}</h3><div class="subtitle">${esc(when(e.ended_unix_ms))} · ${dur(s.encounter_ms)}</div></div><div class="compare-body"><div class="compare-metrics">${mini('Damage',compact(s.total_damage))}${mini('Healing',compact(s.total_healing))}${mini('Taken',compact(s.total_damage_taken))}${mini('Players',rows.length)}</div><div class="section-head" style="padding-left:0;border:0">Damage ranking</div>${rows.map((r,i)=>`<div class="compare-player"><span class="rank">${i+1}</span><span class="name">${esc(r.name||`Player ${r.uid||''}`)}<span class="muted"> · ${esc(r.subprofession_name||'Unknown spec')}</span></span><span class="value">${compact(r.damage)}</span></div>`).join('')||'<div class="muted">No player rows.</div>'}</div></section>`;}
function applySearch(){const q=(search.value||'').trim().toLocaleLowerCase();filtered=DATA.filter(e=>{if(!q)return true;const rows=e.snapshot?.rows||[];return [encounterTitle(e),e.target_name,e.context?.difficulty,e.context?.benchmark_name,...rows.map(r=>r.name),...rows.map(r=>r.subprofession_name)].join(' ').toLocaleLowerCase().includes(q)});if(!filtered.some(e=>e.id===selectedId))selectedId=filtered[0]?.id??null;selectedPlayer=0;tab='overview';compareMode=false;renderList();renderDetail();}
$('#refresh').onclick=()=>location.reload();compareBtn.onclick=()=>{if(compareIds.length===2){compareMode=true;renderDetail()}};search.addEventListener('input',applySearch);document.addEventListener('keydown',ev=>{if(ev.key==='/'&&document.activeElement!==search){ev.preventDefault();search.focus()}else if(ev.key==='Escape'&&search.value){search.value='';applySearch();search.focus()}});renderList();renderDetail();
</script>
</body></html>
"#;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{encounter_context::EncounterContextSnapshot, encounter_store, model::{DpsRow, DpsSnapshot}};
    use std::time::{SystemTime, UNIX_EPOCH};

    #[test]
    fn generates_v127_history_controls_without_gear() {
        let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let root = std::env::temp_dir().join(format!("readyalert-encounter-html-v127-{}-{nonce}", std::process::id()));
        let snapshot = DpsSnapshot { encounter_ms: 1_000, total_damage: 12_345, rows: vec![DpsRow { uid: 1, name: "Alice".into(), damage: 12_345, ..Default::default() }], ..Default::default() };
        let context = EncounterContextSnapshot { scene_id: 1151, scene_name: "Void - Towering Ruin".into(), ..Default::default() };
        encounter_store::archive(&root, &snapshot, &context, 10).unwrap();
        let path = generate(&root).unwrap();
        let html = fs::read_to_string(path).unwrap();
        assert!(html.contains("Refresh"));
        assert!(html.contains("Compare"));
        assert!(html.contains("data-sort"));
        assert!(html.contains("Void - Towering Ruin"));
        assert!(!html.contains("['gear','Gear']"));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn benchmark_metadata_is_rendered_by_local_page_logic() {
        assert!(HTML_TAIL.contains("Benchmark -"));
        assert!(HTML_TAIL.contains("benchmark_duration_ms"));
    }
}
